\pard\fi0\li0\tx570\ql\ri0\sb0\sa0\itap0 \plain \f0\fs24  \plain \f1\fs24 4. (442v-453r) \plain \f2\b\lang1033\fs24 Georgius Pletho, \plain \f1\fs24 Ex Aristotelis de Animalium Historiis lib. I-IX epitome (Ms.\plain \f3\lang1032\fs24 \u8127 ?\u917 \'c5\u954 \'ea \u964 \'f4\u959 \'ef\u965 \'f5 [!] \u960 \'f0\u949 \'e5\u961 \'f1\u8054 ? \u950 \'e6\u8180 ?\u969 \'f9\u957 \'ed \u7985 ?\u963 \'f3\u964 \'f4\u959 \'ef\u961 \'f1\u8055 ?\u945 \'e1\u962 \'f2 \u8127 ?\u913 \'c1\u961 \'f1\u953 \'e9\u963 \'f3\u964 \'f4\u959 \'ef\u964 \'f4\u8051 ?\u955 \'eb\u959 \'ef\u965 \'f5\u962 \'f2\plain \f1\fs24 ); \plain \f2\i\lang1033\fs24 inc\plain \f1\fs24 . \plain \f3\lang1032\fs24 \u932 \'d4\u8182 ?\u957 \'ed \u950 \'e6\u8180 ?\u969 \'f9\u957 \'ed \u964 \'f4\u8048 ? \u956 \'ec\u8050 ?\u957 \'ed \u967 \'f7\u949 \'e5\u961 \'f1\u963 \'f3\u945 \'e1\u8150 ?\u945 \'e1 \u7952 ?\u963 \'f3\u964 \'f4\u8055 ?, \u964 \'f4\u8048 ? \u948 \'e4\u8050 ? \u7956 ?\u957 \'ed\u965 \'f5\u948 \'e4\u961 \'f1\u945 \'e1\plain \f1\fs24 (vgl. I. \plain \f2\scaps\lang1033\fs24 Bekker\plain \f1\fs24 , Aristotelis opera I, Berlin 1831, 487a11);\plain \f2\i\lang1033\fs24 des\plain \f1\fs24 . \plain \f3\lang1032\fs24 \u949 \'e5\u7984 ? \u954 \'ea\u945 \'e1\u8054 ? \u948 \'e4\u949 \'e5\u954 \'ea\u8049 ?\u956 \'ec\u951 \'e7\u957 \'ed\u945 \'e1 \u7952 ?\u964 \'f4\u8055 ?\u954 \'ea\u964 \'f4\u949 \'e5\u964 \'f4\u959 \'ef\plain \f1\fs24 (vgl. 584a6), \plain \f3\lang1032\fs24 \u960 \'f0\u961 \'f1\u959 \'ef\u949 \'e5\u954 \'ea\u960 \'f0\u8055 ?\u960 \'f0\u964 \'f4\u949 \'e5\u953 \'e9\u957 \'ed \u948 \'e4\u8050 ? ... \u954 \'ea\u945 \'e1\u8054 ? \u8017 ?\u947 \'e3\u961 \'f1\u8057 ?\u957 \'ed, \u8003 ? \u954 \'ea\u945 \'e1\u955 \'eb\u959 \'ef\u8166 ?\u963 \'f3\u953 \'e9\u957 \'ed \u8021 ?\u948 \'e4\u961 \'f1\u969 \'f9\u960 \'f0\u945 \'e1 \plain \f1\fs24 (vgl. 587a6). - Im oberen Freirand in Rot: \plain \f3\lang1032\fs24 \u8127 ?\u917 \'c5\u954 \'ea \u964 \'f4\u8182 ?\u957 \'ed \u928 \'d0\u955 \'eb\u951 \'e7\u952 \'e8\u969 \'f9\u957 \'ed\u8055 ?\u969 \'f9\u957 \'ed \u954 \'ea\u945 \'e1\u8054 ? \u964 \'f4\u959 \'ef\u8166 ?\u964 \'f4\u959 \'ef\plain \f1\fs24 . 
